<script setup lang="ts">import {onMounted,computed} from 'vue';import {useLab} from '../stores/laboratory';import {useTask} from '../hooks/useTask';import PageTitle from '../components/common/PageTitle.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import MethodSummary from '../components/MethodSummary.vue';import AgreementPlot from '../components/AgreementPlot.vue';import {number} from '../utils/format';const lab=useLab(),{error,perform}=useTask();const latest=computed(()=>lab.runs.find(r=>r.status==='completed'));const comparisons=computed(()=>{const seen=new Set<number>();return lab.runs.filter(r=>{if(r.status!=='completed'||seen.has(r.dataset_id))return false;seen.add(r.dataset_id);return true;}).slice(0,3);});onMounted(()=>perform(lab.load));</script><template><PageTitle index="01" title="把相同的变化，与相同的读数分开看" text="双侧误差回归、差值界限与适用范围，在同一本研究记录中核对。"><RouterLink class="outline" to="/runs">建立新的比对研究 +</RouterLink></PageTitle><ErrorNotice :message="error" @retry="perform(lab.load)"/><section class="overview-lead"><div class="lead-copy"><p class="eyebrow">RESEARCH POSITION / 当前研究</p><h2>相关很高，<br>仍需核对测量差异。</h2><p>把新仪器放到参考仪器旁边，<br>从系统偏差到高量程波动逐一查证。</p><div class="inventory"><span><b>{{lab.instruments.length}}</b> 台仪器</span><span><b>{{lab.datasets.reduce((n,d)=>n+d.row_count,0)}}</b> 对样本</span><span><b>{{lab.runs.length}}</b> 份研究</span></div><RouterLink v-if="latest" :to="'/results?run='+latest.id">读取最新研究记录 <span>↗</span></RouterLink></div><AgreementPlot v-if="latest" :result="latest.result" kind="ba"/><MethodSummary v-if="latest" :run="latest"/></section><section class="comparison-directory"><div class="section-heading"><h2>三种条件，逐一比对</h2><span>PAIR DATASETS / 反射率百分数</span></div><RouterLink class="study-row" v-for="(r,i) in comparisons" :key="r.id" :to="'/results?run='+r.id"><span class="study-index">0{{i+1}}</span><div><h3>{{r.name}}</h3><p>{{lab.datasets.find(d=>d.id===r.dataset_id)?.note}}</p></div><div class="study-bias"><small>平均偏差</small><b>{{number(r.result.bias,3)}}<em>百分点</em></b></div><span class="study-verdict" :class="r.result.raw_eligible?'green':'plum'">{{r.result.raw_eligible?'达到互换门槛':'需限定用途'}}</span><span>↗</span></RouterLink></section><p class="research-footnote">互换门槛使用预设允许误差与一致性界限的外侧bootstrap CI。高相关性不会触发资格批准。</p></template>
